import { CommonModule } from '@angular/common';
import { Component, Inject, Injectable, Input, OnInit } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { NgxDropzoneChangeEvent, NgxDropzoneModule } from 'ngx-dropzone';
import { ConfirmService } from 'nmce';
import { Observable } from 'rxjs';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';
import { ByteFormatPipe } from './byteFormat.pipe';

/**
 * Use HTML File API to load a local file, and define the description. Return UploadBrief.
 */
@Component({
    templateUrl: 'confirmUpload.component.html',
    standalone: true,
	imports: [CommonModule, FormsModule, NGMDModule, ReactiveFormsModule, NgxDropzoneModule,
		ByteFormatPipe,
	]
})
export class ConfirmUploadComponent implements OnInit {
	@Input()
	title: string;

	@Input()
	body: string;

	mimeType?: string;
	file?: File;
	name?: string;
	description?: string;
	fileSize?: number;

	acceptFilter = '';

	files: File[] = [];

	get isSmallScreen() {
		return APP_DI_CONFIG.isSmallScreen;
	}

	get actionsAlign() {
		return APP_DI_CONFIG.DialogActionsAlign;
	}

	fileOperationHint = $localize`Drop file here, or click to select from file system`;

	constructor(@Inject(MAT_DIALOG_DATA) data: { title: string, body: string, acceptFilter?: string }, public dialogRef: MatDialogRef<ConfirmUploadComponent, UploadBrief>, private confirmService: ConfirmService) {
		this.title = data.title;
		this.body = data.body;
		this.acceptFilter = data.acceptFilter ?? 'image/*,video/*,text/*,audio/*';
	}

	ngOnInit() {
		if (this.isSmallScreen) {
			this.fileOperationHint = `Click to select from device file system`;
		}
	}

	confirm(): void {
		if (!this.file) {
			console.warn('Why confirm? while file missing.');
			return;
		}

		if (this.mimeType) {
			this.dialogRef.close({ file: this.file, mimeType: this.mimeType, name: this.name, description: this.description });
		} else {
			this.confirmService.open($localize`Warning`, $localize`File type of selected file ${this.file.name} is unrecognized. If you upload it then it may not be displayed in the future. Do you want to upload it?`).subscribe(
				data => {
					if (data) {
						this.dialogRef.close({ file: this.file, mimeType: this.mimeType, name: this.name, description: this.description });
					} else {
						this.dialogRef.close();
					}
				}
			);
		}
	}

	//fileChangeListener($event: any) {
	//	const fileList: FileList = $event.target.files;
	//	if (fileList.length > 0) {
	//		this.file = fileList[0];
	//		this.mimeType = this.file.type; // if file.type is not good enough, this might help: https://stackoverflow.com/questions/18299806/how-to-check-file-mime-type-with-javascript-before-upload
	//		this.name = this.file.name;
	//		this.fileSize = this.file.size;
	//	}
	//}

	getFileSizeWarning() {
		if (!this.fileSize || !this.file?.size) {
			return '';
		}

		const MB100 = 2^24; //16MB, MediumBlob
		return this.fileSize >= MB100 ?
			$localize`File size is ${ByteFormatPipe.formatBytes(this.file.size)}, and it is currently too large to be uploaded.`
			:
			$localize`File size is ${ByteFormatPipe.formatBytes(this.file.size)}, and it may take sometime to upload.`;
	}

	onFileSelect(event: NgxDropzoneChangeEvent) {
		console.log(event);
		if (event.addedFiles.length > 0) {
			this.files = [];
			this.file = event.addedFiles[0];
			this.files.push(this.file);
			this.name = this.file.name;
			this.fileSize = this.file.size;
			this.mimeType = this.file.type; 
		}
	}

	onFileRemove(file: File) {
		console.log(file);
		//this.files.splice(this.files.indexOf(file), 1);
	}

}


@Injectable()
export class ConfirmUploadService {
	modalRef?: MatDialogRef<ConfirmUploadComponent>;

	constructor(private dialog: MatDialog) { }

	open(title: string, body: string, acceptFilter?: string): Observable<UploadBrief> {
		this.modalRef = this.dialog.open(ConfirmUploadComponent, { disableClose: true, data: { title: title, body: body, acceptFilter: acceptFilter } });
		console.debug('acceptFiltersssssss: ' + acceptFilter);
		//if (acceptFilter !== undefined) {
		//	this.modalRef.componentInstance.acceptFilter = acceptFilter;
		//	console.debug('acceptFilter: ' + acceptFilter);
		//}

		return this.modalRef.afterClosed();
	}

	openDefault(): Observable<UploadBrief> {
		return this.open($localize`Confirm Upload`, $localize`Select a file to upload.`);
	}
}

export interface UploadBrief {
	file?: File;
	mimeType?: string;
	name?: string;
	description?: string;
}
